            for v, c in adj[u]:
                target = 1.0 if c == 1 else 2.0
                if not visited[v]:
                    visited[v] = True
                    assignment[v] = target - assignment[u]
                    queue.append(v)
                else:
                    if abs(assignment[u] + assignment[v] - target) > 1e-6:
                        has_error = True
                        break
            if has_error:
                break

    if has_error:
        return "NO"

    result = []
    for i in range(1, n + 1):
        val = assignment[i]
        if abs(val - round(val)) < 1e-9:
            result.append(f"{int(round(val))}")
        else:
            result.append(f"{val:.2f}")

    return "YES\n" + " ".join(result)
