def solution(input_str):
    import random

    n = int(input_str.split('\n')[0])

    ships = []
    for i in range(n):
        coords = input_str.split('\n')[1 + i].split()
        ships.append((int(coords[0]), int(coords[1]), i))

    bases = []
    for i in range(n):
        coords = input_str.split('\n')[1 + n + i].split()
        bases.append((int(coords[0]), int(coords[1]), i))

    def cross_product(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    def segments_intersect(p1, p2, p3, p4):
        d1 = cross_product(p3, p4, p1)
        d2 = cross_product(p3, p4, p2)
        d3 = cross_product(p1, p2, p3)
        d4 = cross_product(p1, p2, p4)
        if ((d1 > 0 and d2 < 0) or (d1 < 0 and d2 > 0)) and \
           ((d3 > 0 and d4 < 0) or (d3 < 0 and d4 > 0)):
            return True
        return False

    best_match = None
    best_score = float('inf')

    for _ in range(min(5000, n * n * n)):
        random.seed()
        matching = {i: random.randint(0, n - 1) for i in range(n)}
        matching_keys = list(range(n))

        valid = True
        score = 0
        for i in range(n):
            for j in range(i + 1, n):
                si, sj = matching[matching_keys[i]], matching[matching_keys[j]]
                if segments_intersect(ships[i], ships[j], bases[si], bases[sj]):
                    valid = False
                    score += 1

        if valid:
            result = [matching[i] + 1 for i in range(n)]
            return '\n'.join(map(str, result))

    matching = {i: i + 1 for i in range(n)}
    result = [matching[i] for i in range(n)]
    return '\n'.join(map(str, result))
