Looking at this problem, I need to find the k-th digit in an infinite sequence formed by concatenating blocks where block i contains the sequence "123...i".

Let me analyze the structure:
- Block 1: "1" (1 digit)
- Block 2: "12" (2 digits)
- Block 3: "123" (3 digits)
- ...
- Block 10: "12345678910" (11 digits since "10" has 2 digits)

The key insight is to first find which block contains the k-th digit, then find which digit within that block.

```python
def count_in_range(start, end):
    """Count total digits in numbers from start to end (inclusive)"""
    if start > end:
        return 0

    count = 0

    for length in range(1, 19):
        start_len = 10**(length - 1) if length > 1 else 1
        end_len = 10**length - 1

        start_bound = max(start_len, start)
        end_bound = min(end_len, end)

        if start_bound <= end_bound:
            count += (end_bound - start_bound + 1) * length

    return count

def block_length(n):
    """Calculate total digits in block n (sequence "123...n")"""
    if n <= 0:
        return 0

    return count_in_range(1, n)

def find_digit(k):
    """Find the k-th digit in the infinite sequence"""
    if k <= 0:
        raise ValueError("k must be positive")

    pos = k
    n = 1

    # Find which block contains the k-th digit
    while True:
        bl = block_length(n)
        if pos <= bl:
            # k is in block n
            offset = pos - 1
            num = 1
            remaining = offset

            while remaining > 0:
                num += 1
                digit_count = len(str(num))
                if remaining < digit_count:
                    break
                remaining -= digit_count

            s_num = str(num)
            return s_num[remaining]

        pos -= bl
        n += 1

def solution(input_str):
    # Handle potentially empty input
    if not input_str or not input_str.strip():
        return ""

    lines = input_str.strip().split('\n')
    try:
        q = int(lines[0])
    except ValueError:
        return ""

    results = []
    for i in range(1, q + 1):
        if i < len(lines):
            try:
                k = int(lines[i])
                results.append(str(find_digit(k)))
            except ValueError:
                results.append("0")
        else:
            break

    return '\n'.join(results)

