def solution(input_str):
    """
    Solution for finding the k-th digit in the infinite sequence.

    The sequence is formed by concatenating blocks:
    Block 1: "1"
    Block 2: "12"
    Block 3: "123"
    ...
    Block n: "123...n"

    Input: String containing q followed by q lines each with a k value
    Output: String containing q lines with the digit at position k for each query
    """
